const boardSummaryRuntime=String.raw`function boardOwnSummary(owner){const deck=chosen(),enabled=S.boardEnabled!==false,labels={leader:"リーダー時",self:"編成時",global:"常時",song:"楽曲時"},buckets={leader:[],self:[],global:[],song:[]},active={leader:!!lead()&&lead().member===owner.member,self:deck.some(c=>c.id===owner.id),global:true,song:true};for(const id of getBoardSet(owner.id)){const node=D.board?.nodes?.find(n=>n.id===id),effect=node&&parseBoardEffect(node.text);if(!effect||!buckets[node.color])continue;buckets[node.color].push(effect)}const format=effects=>{const values={performance:{pct:0,flat:0},technique:{pct:0,flat:0},sense:{pct:0,flat:0}},extra={scoreSupport:0,scoreBonus:0,rate:0,frequency:0};for(const e of effects){if(e.kind==="param"){const stats=e.stat==="all"?["performance","technique","sense"]:[e.stat];for(const stat of stats)values[stat][e.percent?"pct":"flat"]+=e.value}else if(e.kind in extra)extra[e.kind]+=e.value}const parts=[];for(const [stat,label] of [["performance","P"],["technique","T"],["sense","S"]]){const v=values[stat],text=[];if(v.pct)text.push("+"+v.pct+"%UP");if(v.flat)text.push("+"+v.flat+"UP");if(text.length)parts.push(label+" "+text.join(" / "))}if(extra.scoreSupport)parts.push("サポート +"+extra.scoreSupport+"%");if(extra.scoreBonus)parts.push("スコア +"+extra.scoreBonus+"%");if(extra.rate)parts.push("A発動率 +"+extra.rate+"%");if(extra.frequency)parts.push("A頻度 +"+extra.frequency+"%");return parts.join(" ・ ")};const rows=Object.entries(buckets).filter(([,effects])=>effects.length).map(([role,effects])=>"<div class='board-summary-row'><span>"+labels[role]+"</span><b>"+format(effects)+"</b><em class='"+(enabled&&active[role]?"is-on":"is-off")+"'>"+(enabled&&active[role]?"反映中":"未反映")+"</em></div>").join("");return "<div class='board-own-summary'><div class='board-summary-title'>このボードの解放合計</div>"+(rows||"<div class='muted'>効果マスは未解放です。</div>")+"<small>他カードのボード・通常スキルは含みません。</small></div>"}`;
